// single-item input: the runs endpoint answers one object holding the list.
const cfg = $('Settings').first().json;
const body = $input.first().json || {};

// neverError is on, so a wrong owner or repo arrives here as a green node with
// a JSON body instead of an HTTP error. The message field is the only sign.
if (body.message) {
  throw new Error(
    'GitHub answered "' + body.message + '" for ' + cfg.owner + '/' + cfg.repo +
    '. Check the owner, the repo and that the token can read Actions.'
  );
}

const runs = body.workflow_runs || [];
if (!runs.length) {
  throw new Error(
    'No completed runs came back for branch ' + cfg.branch + '. Check the ' +
    'branch name - a repository that renamed master to main returns an empty ' +
    'list rather than an error.'
  );
}

const wanted = String(cfg.workflow_name || '').trim().toLowerCase();
const mine = runs.filter(r => String(r.name || '').toLowerCase() === wanted);

if (!mine.length) {
  // Dependabot names a run after the whole dependency update, so the raw list
  // is 300 characters of npm packages before the workflow you wanted.
  const seen = Array.from(new Set(runs.map(r => String(r.name || ''))))
    .map(x => (x.length > 44 ? x.slice(0, 41) + '...' : x))
    .slice(0, 10);
  throw new Error(
    'No runs named "' + cfg.workflow_name + '" on ' + cfg.branch + '. The ' +
    'workflows that did run: ' + seen.join(', ')
  );
}

// conclusion is not two-valued. Measured across 400 runs of three repositories:
// success, failure, cancelled, skipped, action_required and null while still
// running. A cancelled run is not evidence of anything - home-assistant/core
// had four of them in its last seven - and counting them as failures makes
// every busy repository look broken.
const PASS = new Set(['success']);
const FAIL = new Set(['failure', 'timed_out']);

const maxRuns = Math.max(3, Number(cfg.runs_to_read) || 12);
const usable = mine
  .filter(r => PASS.has(r.conclusion) || FAIL.has(r.conclusion))
  .slice(0, maxRuns);

if (!usable.length) {
  throw new Error(
    'Every recent run of "' + cfg.workflow_name + '" was cancelled or skipped, ' +
    'so there is nothing to judge. Widen runs_to_read or pick another workflow.'
  );
}

// This endpoint sometimes answers from a stale index. Measured on 2026-09-02:
// three identical requests one second apart reported total_count 36425, 29277
// and 36425, and one run of this workflow was handed a page whose newest entry
// was three months old - total_count 5980. Nothing in the response marks it as
// stale. A flake report built on a window from June, presented as this week, is
// worse than no report, so the age of the newest run is checked out loud.
const staleDays = Math.max(1, Number(cfg.stale_after_days) || 14);
const newest = new Date(usable[0].run_started_at || usable[0].created_at);
const ageDays = (Date.now() - newest.getTime()) / 86400000;

if (ageDays > staleDays) {
  throw new Error(
    'The newest run GitHub returned started ' + Math.round(ageDays) +
    ' days ago (' + newest.toISOString().slice(0, 10) + '). GitHub serves this ' +
    'list from a stale index now and again - three identical requests have ' +
    'returned three different totals. Run it again; if the date does not move, ' +
    'this workflow really has not run since then.'
  );
}

const out = [];

for (const r of usable) {
  const attempts = [r.run_attempt || 1];

  // The list shows the last attempt only. A run that was re-run until it passed
  // reports success, and the failures underneath it are the strongest flake
  // evidence there is: the same commit produced both answers. Attempt 1 is
  // queued for reading whenever there was more than one.
  if ((r.run_attempt || 1) > 1) attempts.push(1);

  for (const n of attempts) {
    out.push({
      json: {
        run_id: r.id,
        attempt: n,
        is_earlier_attempt: n < (r.run_attempt || 1),
        run_conclusion: r.conclusion,
        head_sha: String(r.head_sha || '').slice(0, 7),
        run_url: r.html_url,
        started: r.run_started_at,
      },
    });
  }
}

return out;

// Every page of every attempt arrives here as its own item, and each job in it
// names its own run and attempt - run_id, run_attempt, workflow_name - so the
// pages do not have to be matched back to the request that produced them.
const cfg = $('Settings').first().json;
const minRuns = Math.max(2, Number(cfg.min_observations) || 3);

const PASS = new Set(['success']);
const FAIL = new Set(['failure', 'timed_out']);

// Which attempts were superseded by a later one that passed. A failure inside
// one of those is a confirmed flake rather than a suspicion, because a later
// attempt of the same commit went green.
const rerunGreen = new Set();
for (const r of $('Pick The Runs Worth Reading').all()) {
  const d = r.json;
  if (d.is_earlier_attempt && d.run_conclusion === 'success') {
    rerunGreen.add(String(d.run_id) + '#' + d.attempt);
  }
}

let truncated = 0;
let attemptsRead = 0;
const jobs = [];

for (const item of $input.all()) {
  const body = item.json || {};
  if (body.message) continue;
  const page = body.jobs || [];
  if (!page.length) continue;
  attemptsRead += 1;
  for (const j of page) jobs.push(j);
}

if (!jobs.length) {
  throw new Error(
    'None of the runs returned any jobs. A run sitting in action_required has ' +
    'no jobs at all, and a token without the Actions read scope returns the ' +
    'same empty shape.'
  );
}

const byName = {};

for (const j of jobs) {
  const name = String(j.name || 'unnamed');
  if (!byName[name]) {
    byName[name] = {
      job_name: name,
      workflow: j.workflow_name || cfg.workflow_name,
      passes: 0,
      failures: 0,
      confirmed: 0,
      steps: {},
      last_failure_url: '',
      shas: new Set(),
      failed_runs: new Set(),
    };
  }
  const g = byName[name];
  const key = String(j.run_id) + '#' + (j.run_attempt || 1);

  if (PASS.has(j.conclusion)) {
    g.passes += 1;
  } else if (FAIL.has(j.conclusion)) {
    g.failures += 1;
    g.failed_runs.add(String(j.run_id));
    g.last_failure_url = j.html_url || g.last_failure_url;
    if (rerunGreen.has(key)) g.confirmed += 1;
    for (const s of j.steps || []) {
      if (FAIL.has(s.conclusion)) {
        g.steps[s.name] = (g.steps[s.name] || 0) + 1;
      }
    }
  } else {
    // skipped, cancelled, neutral, still running. Not an observation.
    continue;
  }
  g.shas.add(String(j.head_sha || '').slice(0, 7));
}

const out = [];

for (const name of Object.keys(byName)) {
  const g = byName[name];
  const seen = g.passes + g.failures;
  if (!g.failures) continue;

  // A job that has only ever failed is broken, not flaky, and telling an
  // engineer to "look into the flakiness" of a job that has failed nine times
  // out of nine wastes their afternoon. Measured on a real repository: one of
  // the six mixed jobs was a lint step called "Check PR title is not
  // Conventional Commits", which fails on purpose.
  //
  // And a job that failed in exactly one run is one bad day, not randomness.
  // Measured on apache/airflow: ten job names each failed once in six runs and
  // read as ten flaky jobs - but all ten failures came from two runs, six cells
  // of one matrix in one and four in another. That is two incidents. Two
  // different runs is the smallest evidence of a job answering differently on
  // different days.
  let verdict = 'broken';
  if (g.confirmed) verdict = 'confirmed flake';
  else if (g.passes && g.failed_runs.size < 2) verdict = 'one bad run';
  else if (g.passes && seen >= minRuns) verdict = 'flaky';
  else if (g.passes) verdict = 'too few runs';

  out.push({
    json: {
      job_key: (g.workflow + ' / ' + name).slice(0, 200),
      job_name: name,
      workflow: g.workflow,
      verdict,
      passes: g.passes,
      failures: g.failures,
      confirmed: g.confirmed,
      runs_seen: seen,
      failed_in_runs: g.failed_runs.size,
      flake_rate: seen ? Math.round((g.failures / seen) * 100) : 0,
      distinct_commits: g.shas.size,
      // A matrix step name carries the whole cell - one of them was 400
      // characters of provider names - and unwrapped it buries the report.
      failing_steps: Object.keys(g.steps)
        .sort((a, b) => g.steps[b] - g.steps[a])
        .slice(0, 3)
        .map(x => (x.length > 90 ? x.slice(0, 87).trim() + '...' : x)),
      example: g.last_failure_url,
    },
  });
}

out.sort((a, b) =>
  b.json.confirmed - a.json.confirmed ||
  b.json.flake_rate - a.json.flake_rate ||
  b.json.failures - a.json.failures
);

if (!out.length) {
  // A filtering step that can return nothing ends the branch, and every node
  // below it silently never runs. One marker item keeps the quiet path alive.
  return [{
    json: {
      job_key: '',
      verdict: 'all green',
      attempts_read: attemptsRead,
      truncated,
    },
  }];
}

out[0].json.attempts_read = attemptsRead;
return out;

// reads the table: $input is the stored history on purpose. The fresh scores
// come from Score Every Job by name, because a Data Table read replaces the
// item exactly the way a Set node does.
const cfg = $('Settings').first().json;
const fresh = $('Score Every Job').all().map(i => i.json).filter(j => j.job_key);

const history = {};
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.job_key) history[String(r.job_key)] = r;
}

const worsenBy = Math.max(1, Number(cfg.report_when_worse_by) || 10);
const report = [];

for (const f of fresh) {
  // "broken" and "too few runs" are real states worth storing, but they are not
  // what this workflow is for and they do not go to Slack.
  if (f.verdict !== 'flaky' && f.verdict !== 'confirmed flake') continue;

  const prev = history[f.job_key];
  if (!prev) {
    report.push(Object.assign({}, f, { why: 'new' }));
    continue;
  }
  const before = Number(prev.flake_rate) || 0;
  if (f.flake_rate - before >= worsenBy) {
    report.push(Object.assign({}, f, {
      why: 'worse, was ' + before + '%',
      previous_rate: before,
    }));
  }
}

const stored = fresh.filter(f => f.verdict !== 'all green');

return [{
  json: {
    report,
    report_count: report.length,
    stored,
    scanned: fresh.length,
    broken: fresh.filter(f => f.verdict === 'broken').length,
    one_off: fresh.filter(f => f.verdict === 'one bad run').length,
    one_off_runs: Array.from(new Set(
      fresh.filter(f => f.verdict === 'one bad run').map(f => f.example)
    )).length,
    attempts_read: (fresh[0] && fresh[0].attempts_read) || 0,
    for_model: report.slice(0, 12).map(r => ({
      job: r.job_name,
      verdict: r.verdict,
      failures: r.failures,
      of: r.runs_seen,
      steps: r.failing_steps,
    })),
  },
}];

// single-item input: one summary covering every flaky job.
const d = $('Only The New Or Worse').first().json;
const note = String($input.first().json.text || '').trim();
const lines = [];
const cfg = $('Settings').first().json;

lines.push('*Flaky CI* - ' + cfg.owner + '/' + cfg.repo + ' - ' +
  cfg.workflow_name + ' on ' + cfg.branch);
lines.push('Read ' + d.attempts_read + ' attempts. ' + d.report_count +
  ' job' + (d.report_count === 1 ? '' : 's') + ' worth reporting' +
  (d.broken ? ', plus ' + d.broken + ' failing every time (not flaky)' : '') +
  '.');

// Said out loud rather than silently dropped: a matrix that goes red together
// looks like fifty flaky jobs and is one incident.
if (d.one_off) {
  lines.push(d.one_off + ' more failed in a single run each and are held back ' +
    'as one bad day rather than randomness.');
}
lines.push('');

for (const r of d.report) {
  const mark = r.verdict === 'confirmed flake' ? ':rotating_light:' : ':warning:';
  lines.push(mark + ' *' + r.job_name + '* - ' + r.failures + ' of ' +
    r.runs_seen + ' (' + r.flake_rate + '%)' +
    (r.why === 'new' ? '' : ' - ' + r.why));

  if (r.confirmed) {
    lines.push('    ' + r.confirmed + ' of those failures was on a commit that ' +
      'passed on a later attempt, so the code was identical');
  }
  if ((r.failing_steps || []).length) {
    lines.push('    failing step: ' + r.failing_steps.join(', '));
  }
  if (r.example) lines.push('    ' + r.example);
}

if (note) {
  lines.push('');
  lines.push(note);
}

return [{ json: { message: lines.join('\n').slice(0, 3800) } }];

// One issue per confirmed flake - a job that failed on an attempt and passed on
// another attempt of the same commit. Suspicion is a Slack line; proof is worth
// a ticket somebody has to close.
//
// Returning nothing here ends this branch, which is exactly right: this is a
// leaf and nothing downstream needs to run when there is nothing to file. The
// rule about filters that can return zero items applies to a filter with work
// below it.
const d = $('Only The New Or Worse').first().json;
const cfg = $('Settings').first().json;

return (d.report || [])
  .filter(r => r.verdict === 'confirmed flake')
  .slice(0, Math.max(1, Number(cfg.max_issues_per_run) || 3))
  .map(r => {
    const body = [
      '`' + r.job_name + '` failed ' + r.failures + ' of ' + r.runs_seen +
        ' times on `' + cfg.branch + '` (' + r.flake_rate + '%).',
      '',
      r.confirmed + ' of those failures happened on a commit that passed on a ' +
        'later attempt of the same run, so the code was identical in both.',
      '',
      (r.failing_steps || []).length
        ? 'Failing step: ' + r.failing_steps.join(', ')
        : 'No failing step was named in the job.',
      '',
      r.example ? 'Example: ' + r.example : '',
      '',
      'Filed from the ' + cfg.workflow_name + ' workflow.',
    ].join(String.fromCharCode(10));

    return {
      json: {
        title: 'Flaky job: ' + String(r.job_name).slice(0, 120),
        body,
      },
    };
  });

// Every job that failed at all, not only the ones that were reported. Next
// week's "worse than it was" needs the rate from a week nobody was told about.
const stored = $('Only The New Or Worse').first().json.stored || [];
const today = new Date().toISOString().slice(0, 10);

if (!stored.length) {
  return [{
    json: {
      job_key: 'nothing failed on ' + today,
      job_name: '',
      flake_rate: 0,
      failures: 0,
      runs_seen: 0,
      verdict: 'all green',
      last_seen: today,
    },
  }];
}

return stored.map(s => ({
  json: {
    job_key: String(s.job_key),
    job_name: String(s.job_name || ''),
    flake_rate: Number(s.flake_rate) || 0,
    failures: Number(s.failures) || 0,
    runs_seen: Number(s.runs_seen) || 0,
    verdict: String(s.verdict || ''),
    last_seen: today,
  },
}));
